class BadHash(private val id: String) {
    override fun equals(other: Any?): Boolean {
        if (this === other) return true
        if (other !is BadHash) return false
        return id == other.id
    }

    override fun hashCode(): Int {
        return super.hashCode() // bad
    }
}

class GoodExplicit(private val id: String) {
    override fun equals(other: Any?): Boolean {
        if (this === other) return true
        if (other !is GoodExplicit) return false
        return id == other.id
    }

    override fun hashCode(): Int {
        return id.hashCode()
    }
}
